'use client';

import { useEffect, useRef, useState } from 'react';
import { toPng } from 'html-to-image';

export interface CardMember {
  id: string;
  name: string;
  father_name: string;
  cnic?: string | null;
  b_form?: string | null;
  phone?: string | null;
  photo_url?: string | null;
}

// Card ki images (background + logo) isi file mai embed hain, alag se koi file rakhne ki zaroorat nahi.
const CARD_BG = 'data:image/webp;base64,';
const LOGO = 'data:image/webp;base64,';

const CARD_W = 1258;
const CARD_H = 685;
const CARD_RADIUS = 58;

const FONT = "'Roboto Condensed', 'Arial Narrow', 'Helvetica Neue', Arial, sans-serif";

/* ───────────────────────── FRONT ───────────────────────── */
const JAMAT_EMAIL = 'Naliyamandvi786@gmail.com';
const JAMAT_ADDRESS = 'Plot No.68, Soldier Bazar No.02, Karachi.';

const PLATE_X = 506;
const PLATE_W = 432;
const PLATE_H = 76;
const PLATE_TOP = 194;
const PLATE_STEP = 84;

const plateShape = 'polygon(12px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 12px)';

const Plate = ({ index, label, value }: { index: number; label: string; value: string }) => {
  const size = Math.max(18, Math.min(34, Math.floor(370 / (Math.max(value.length, 1) * 0.6))));
  return (
    <div
      style={{
        position: 'absolute',
        left: PLATE_X,
        top: PLATE_TOP + index * PLATE_STEP,
        width: PLATE_W,
        height: PLATE_H,
        filter: 'drop-shadow(0 3px 3px rgba(70,50,20,0.38))',
      }}
    >
      <div style={{ position: 'absolute', inset: 0, clipPath: plateShape, background: 'linear-gradient(180deg,#fffaf0 0%,#b9a07a 100%)' }} />
      <div
        style={{
          position: 'absolute', inset: 2.5, clipPath: plateShape,
          background: 'linear-gradient(100deg,#f8f0de 0%,#eadbbd 55%,#dfcdab 100%)',
          padding: '5px 22px 0 24px', boxSizing: 'border-box',
        }}
      >
        <div style={{ fontSize: 18, fontWeight: 800, color: '#1d1916', letterSpacing: 0.3, lineHeight: '21px' }}>{label}</div>
        <div
          style={{
            fontSize: size, color: '#2a2320', lineHeight: '38px', height: 38,
            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
          }}
        >
          {value}
        </div>
      </div>
    </div>
  );
};

const MailIcon = () => (
  <svg width="26" height="26" viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle cx="12" cy="12" r="12" fill="#1b2a6b" />
    <rect x="5.5" y="7.5" width="13" height="9" rx="1.5" fill="none" stroke="#fff" strokeWidth="1.4" />
    <path d="M6 8.5 L12 13 L18 8.5" fill="none" stroke="#fff" strokeWidth="1.4" />
  </svg>
);
const PinIcon = () => (
  <svg width="26" height="26" viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle cx="12" cy="12" r="12" fill="#1b2a6b" />
    <path d="M12 5.5c-2.6 0-4.6 2-4.6 4.5 0 3.3 4.6 8.5 4.6 8.5s4.6-5.2 4.6-8.5c0-2.5-2-4.5-4.6-4.5z" fill="#fff" />
    <circle cx="12" cy="10" r="1.8" fill="#1b2a6b" />
  </svg>
);

// Background (card-front-bg) aapke diye hue design se bana hai.
// Us ke upar member ka data, photo, logo aur jamat ka email/address lagta hai.
export const CardFront = ({ member }: { member: CardMember }) => {
  const hasCnic = !!member.cnic;
  const fields: { label: string; value: string }[] = [
    { label: 'NAME:', value: member.name },
    { label: 'FATHER NAME:', value: member.father_name },
    { label: 'MEMBER ID:', value: member.id },
    { label: hasCnic ? 'CNIC:' : 'B-FORM:', value: member.cnic || member.b_form || '—' },
    { label: 'PHONE NO:', value: member.phone || '—' },
  ];

  return (
    <div
      style={{
        position: 'relative',
        width: CARD_W,
        height: CARD_H,
        borderRadius: CARD_RADIUS,
        overflow: 'hidden',
        fontFamily: FONT,
        backgroundColor: '#d9c3a0',
      }}
    >
      {/* Design background */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={CARD_BG} alt="" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }} />

      {/* Halka watermark logo (background) */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={LOGO} alt="" style={{ position: 'absolute', left: 560, top: 120, width: 480, opacity: 0.05 }} />

      {/* Logo (left navy panel) */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={LOGO}
        alt="Logo"
        style={{ position: 'absolute', left: 22, top: 142, width: 394, height: 394, objectFit: 'contain' }}
      />

      {/* 5 fields */}
      {fields.map((f, i) => (
        <Plate key={f.label} index={i} label={f.label} value={f.value} />
      ))}

      {/* Photo (design ke frame ke andar) */}
      <div
        style={{
          position: 'absolute', left: 1003, top: 249, width: 172, height: 264,
          overflow: 'hidden', backgroundColor: '#e3d2b4',
        }}
      >
        {member.photo_url && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={member.photo_url}
            alt="Member"
            crossOrigin="anonymous"
            style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', display: 'block' }}
          />
        )}
      </div>
    </div>
  );
};

